//! Dates and times as a locale writes them (D21, D41), from CLDR's
//! Gregorian calendar data (generated by gen.zig): month and weekday
//! names, day periods, date and time patterns, the locale's digits, its
//! first day of the week, and its hour cycle. A locale also has a number
//! record, which number.zig reads.
//!
//! Days are counted from 1970-01-01 in the proleptic Gregorian calendar,
//! without a time zone: a civil date, as a date picker chooses one.
//! Times are seconds since midnight.

const std = @import("std");
const data = @import("cldr_data");

const Writer = std.Io.Writer;

pub const version = data.version;

/// Positions of the strings in a locale record (gen.zig writes them in
/// this order).
const F = struct {
    const month_format_wide: usize = 0;
    const month_format_abbr: usize = 12;
    const month_standalone_wide: usize = 24;
    const month_standalone_abbr: usize = 36;
    const day_format_wide: usize = 48;
    const day_format_abbr: usize = 55;
    const day_standalone_wide: usize = 62;
    const day_standalone_abbr: usize = 69;
    const day_standalone_short: usize = 76;
    const day_standalone_narrow: usize = 83;
    const am: usize = 90;
    const pm: usize = 91;
    const era_bc: usize = 92;
    const era_ad: usize = 93;
    const date_full: usize = 94;
    const time_medium: usize = 98;
    const time_short: usize = 99;
    const year_month: usize = 100;
};

comptime {
    std.debug.assert(data.field_count == 101);
}

pub const DateStyle = enum(u8) {
    /// "Sunday, October 18, 2026"
    full,
    /// "October 18, 2026"
    long,
    /// "Oct 18, 2026"
    medium,
    /// "10/18/26"
    short,
    /// "October 2026"
    month_year,
    /// The day of the month as a number: "18".
    day,
    /// The month's name on its own: "October".
    month,
    /// The weekday's name on its own: "Sunday".
    weekday,
    /// The weekday's short name, for a calendar's column: "Su".
    weekday_short,
    /// The year as a number: "2026".
    year,
    /// The weekday's narrowest name, for a calendar's column where the
    /// short one does not fit: "S", "س".
    weekday_narrow,
};

pub const TimeStyle = enum(u8) {
    /// "10:30 PM"
    short,
    /// "10:30:15 PM"
    medium,
    /// The hour as the short pattern writes it: "10", or "22" or "07".
    hour,
    /// "05"
    minute,
    /// "09"
    second,
    /// "PM"
    period,
};

pub const HourCycle = enum(u8) {
    /// 1 to 12, with a day period.
    h12,
    /// 0 to 23.
    h23,
    /// 0 to 11, with a day period.
    h11,
    /// 1 to 24.
    h24,
};

pub const Locale = struct {
    record: *const [data.field_count]u16,
    /// Number symbols and patterns (number.zig).
    numbers: *const [data.number_field_count]u16,
    /// 0 is Sunday.
    first_day: u3,
    /// Ten code points, UTF-8.
    digits: []const u8,
    tag: []const u8,

    /// The locale data for a BCP 47 tag ("de-AT", "zh-TW", "sr-Latn"),
    /// falling back to shorter tags and then English. The first day of
    /// the week follows the tag's region when it names one.
    pub fn find(language: []const u8) Locale {
        var buf: [64]u8 = undefined;
        var tag = normalize(&buf, language);
        const region = regionOf(tag);
        const entry: *const data.Locale = while (tag.len > 0) {
            if (lookup(tag)) |e| break e;
            // zh-TW goes on as zh-Hant-TW, then zh-Hant.
            if (alias(tag)) |to| {
                tag = to;
                continue;
            }
            tag = tag[0 .. std.mem.lastIndexOfScalar(u8, tag, '-') orelse 0];
        } else lookup("en").?;
        var first: u3 = @intCast(entry.first_day);
        if (region) |r| first = regionFirstDay(r) orelse first;
        return .{ .record = &data.records[entry.record], .numbers = &data.number_records[entry.numbers], .first_day = first, .digits = data.digits[entry.digits], .tag = entry.tag };
    }

    pub fn str(l: Locale, at: usize) []const u8 {
        return poolString(l.record[at]);
    }

    pub fn hourCycle(l: Locale) HourCycle {
        var it: Tokens = .{ .pattern = l.str(F.time_short) };
        while (it.next()) |t| if (t == .field) switch (t.field.letter) {
            'h' => return .h12,
            'H' => return .h23,
            'K' => return .h11,
            'k' => return .h24,
            else => {},
        };
        return .h23;
    }

    /// Whether the day period comes before the hour ("a h:mm" in Korean).
    pub fn periodFirst(l: Locale) bool {
        var it: Tokens = .{ .pattern = l.str(F.time_short) };
        while (it.next()) |t| if (t == .field) switch (t.field.letter) {
            'a', 'b', 'B' => return true,
            'h', 'H', 'K', 'k' => return false,
            else => {},
        };
        return false;
    }

    /// The first character between the hour and the minute: ':' mostly,
    /// '.' in Finnish.
    pub fn timeSeparator(l: Locale) u21 {
        var it: Tokens = .{ .pattern = l.str(F.time_short) };
        var after_hour = false;
        while (it.next()) |t| switch (t) {
            .field => |f| after_hour = switch (f.letter) {
                'h', 'H', 'K', 'k' => true,
                else => false,
            },
            .literal => |s| if (after_hour and s.len > 0) {
                return std.unicode.utf8Decode(s[0 .. std.unicode.utf8ByteSequenceLength(s[0]) catch 1]) catch ':';
            },
        };
        return ':';
    }

    /// Writes a number in the locale's digits, at least `width` of them.
    pub fn number(l: Locale, w: *Writer, n: u64, width: u8) Writer.Error!void {
        var ascii: [24]u8 = undefined;
        const s = std.fmt.bufPrint(&ascii, "{d:0>[1]}", .{ n, width }) catch unreachable;
        const ds = l.digitStrings();
        for (s) |ch| try w.writeAll(ds[ch - '0']);
    }

    /// The locale's ten digits, each as UTF-8.
    pub fn digitStrings(l: Locale) [10][]const u8 {
        var ds: [10][]const u8 = undefined;
        var i: usize = 0;
        for (&ds) |*d| {
            const len = std.unicode.utf8ByteSequenceLength(l.digits[i]) catch 1;
            d.* = l.digits[i..][0..len];
            i += len;
        }
        return ds;
    }

    pub fn formatDate(l: Locale, w: *Writer, days: i64, style: DateStyle) Writer.Error!void {
        const date = Date.fromDays(days);
        const wd = weekday(days);
        switch (style) {
            .full, .long, .medium, .short => try l.pattern(w, l.str(F.date_full + @intFromEnum(style)), date, wd, 0),
            .month_year => try l.pattern(w, l.str(F.year_month), date, wd, 0),
            .day => try l.number(w, date.day, 1),
            .month => try w.writeAll(l.str(F.month_standalone_wide + date.month - 1)),
            .weekday => try w.writeAll(l.str(F.day_standalone_wide + @as(usize, wd))),
            .weekday_short => try w.writeAll(l.str(F.day_standalone_short + @as(usize, wd))),
            .year => try l.number(w, @abs(date.year), 1),
            .weekday_narrow => try w.writeAll(l.str(F.day_standalone_narrow + @as(usize, wd))),
        }
    }

    pub fn formatTime(l: Locale, w: *Writer, seconds: u32, style: TimeStyle) Writer.Error!void {
        const s = seconds % 86400;
        const date: Date = .{ .year = 1970, .month = 1, .day = 1 };
        switch (style) {
            .short => try l.pattern(w, l.str(F.time_short), date, 4, s),
            .medium => try l.pattern(w, l.str(F.time_medium), date, 4, s),
            .hour => {
                var it: Tokens = .{ .pattern = l.str(F.time_short) };
                while (it.next()) |t| if (t == .field) switch (t.field.letter) {
                    'h', 'H', 'K', 'k' => return l.field(w, t.field, date, 4, s),
                    else => {},
                };
                try l.number(w, s / 3600, 2);
            },
            .minute => try l.number(w, s / 60 % 60, 2),
            .second => try l.number(w, s % 60, 2),
            .period => try w.writeAll(l.str(if (s < 43200) F.am else F.pm)),
        }
    }

    fn pattern(l: Locale, w: *Writer, p: []const u8, date: Date, wd: u3, seconds: u32) Writer.Error!void {
        var it: Tokens = .{ .pattern = p };
        while (it.next()) |t| switch (t) {
            .literal => |s| try w.writeAll(s),
            .field => |f| try l.field(w, f, date, wd, seconds),
        };
    }

    fn field(l: Locale, w: *Writer, f: Token.Field, date: Date, wd: u3, seconds: u32) Writer.Error!void {
        const n = f.count;
        const hour = seconds / 3600;
        switch (f.letter) {
            'G' => try w.writeAll(l.str(if (date.year > 0) F.era_ad else F.era_bc)),
            'y' => {
                const y: u64 = if (date.year > 0) @intCast(date.year) else @intCast(1 - date.year);
                if (n == 2) try l.number(w, y % 100, 2) else try l.number(w, y, n);
            },
            'M', 'L' => {
                const standalone = f.letter == 'L';
                switch (n) {
                    1, 2 => try l.number(w, date.month, n),
                    3, 5 => try w.writeAll(l.str((if (standalone) F.month_standalone_abbr else F.month_format_abbr) + date.month - 1)),
                    else => try w.writeAll(l.str((if (standalone) F.month_standalone_wide else F.month_format_wide) + date.month - 1)),
                }
            },
            'd' => try l.number(w, date.day, n),
            'E', 'c' => {
                const standalone = f.letter == 'c';
                const base: usize = switch (n) {
                    1, 2, 3 => if (standalone) F.day_standalone_abbr else F.day_format_abbr,
                    4 => if (standalone) F.day_standalone_wide else F.day_format_wide,
                    5 => F.day_standalone_narrow,
                    else => F.day_standalone_short,
                };
                try w.writeAll(l.str(base + @as(usize, wd)));
            },
            'h' => try l.number(w, if (hour % 12 == 0) 12 else hour % 12, n),
            'H' => try l.number(w, hour, n),
            'K' => try l.number(w, hour % 12, n),
            'k' => try l.number(w, if (hour == 0) 24 else hour, n),
            'm' => try l.number(w, seconds / 60 % 60, n),
            's' => try l.number(w, seconds % 60, n),
            'a', 'b', 'B' => try w.writeAll(l.str(if (seconds < 43200) F.am else F.pm)),
            // Time zones and the rest do not occur in the patterns used.
            else => {},
        }
    }
};

pub const Date = struct {
    year: i32,
    /// 1 to 12.
    month: u8,
    /// 1 to 31.
    day: u8,

    /// From days since 1970-01-01 (Howard Hinnant's civil_from_days).
    pub fn fromDays(days: i64) Date {
        const z = days + 719468;
        const era = @divFloor(z, 146097);
        const doe: u64 = @intCast(z - era * 146097);
        const yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        const doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        const mp = (5 * doy + 2) / 153;
        const d: u8 = @intCast(doy - (153 * mp + 2) / 5 + 1);
        const m: u8 = @intCast(if (mp < 10) mp + 3 else mp - 9);
        const y = @as(i64, @intCast(yoe)) + era * 400 + @intFromBool(m <= 2);
        return .{ .year = @intCast(y), .month = m, .day = d };
    }

    /// Days since 1970-01-01. Months and days out of range carry over
    /// (month 13 is January of the next year, day 0 the last of the
    /// month before).
    pub fn toDays(date: Date) i64 {
        var y: i64 = date.year;
        var m: i64 = date.month;
        y += @divFloor(m - 1, 12);
        m = @mod(m - 1, 12) + 1;
        y -= @intFromBool(m <= 2);
        const era = @divFloor(y, 400);
        const yoe: i64 = y - era * 400;
        const mp: i64 = if (m > 2) m - 3 else m + 9;
        const doy = @divFloor(153 * mp + 2, 5);
        const doe = yoe * 365 + @divFloor(yoe, 4) - @divFloor(yoe, 100) + doy;
        return era * 146097 + doe - 719468 + @as(i64, date.day) - 1;
    }
};

/// 0 is Sunday; 1970-01-01 was a Thursday.
pub fn weekday(days: i64) u3 {
    return @intCast(@mod(days + 4, 7));
}

pub fn daysInMonth(year: i32, month: u8) u8 {
    return @intCast(Date.toDays(.{ .year = year, .month = month + 1, .day = 1 }) - Date.toDays(.{ .year = year, .month = month, .day = 1 }));
}

const Token = union(enum) {
    literal: []const u8,
    field: Field,

    const Field = struct { letter: u8, count: u8 };
};

/// The fields and literals of a CLDR pattern: runs of one ASCII letter
/// are fields; text in single quotes is literal ('' is a quote).
const Tokens = struct {
    pattern: []const u8,
    i: usize = 0,

    fn next(t: *Tokens) ?Token {
        const p = t.pattern;
        if (t.i >= p.len) return null;
        const start = t.i;
        const ch = p[start];
        if (std.ascii.isAlphabetic(ch)) {
            while (t.i < p.len and p[t.i] == ch) t.i += 1;
            return .{ .field = .{ .letter = ch, .count = @intCast(@min(t.i - start, 255)) } };
        }
        if (ch == '\'') {
            if (start + 1 < p.len and p[start + 1] == '\'') {
                t.i += 2;
                return .{ .literal = "'" };
            }
            const end = std.mem.indexOfScalarPos(u8, p, start + 1, '\'') orelse p.len;
            t.i = @min(end + 1, p.len);
            return .{ .literal = p[start + 1 .. end] };
        }
        while (t.i < p.len and !std.ascii.isAlphabetic(p[t.i]) and p[t.i] != '\'') t.i += 1;
        return .{ .literal = p[start..t.i] };
    }
};

/// A string of the pool by index.
pub fn poolString(i: u16) []const u8 {
    return data.pool[data.offsets[i]..data.offsets[i + 1]];
}

/// A POSIX locale name or BCP 47 tag as a tag: "de_AT.UTF-8" is "de-AT";
/// "C" and "POSIX" are empty.
pub fn normalize(buf: []u8, language: []const u8) []const u8 {
    const end = std.mem.indexOfAny(u8, language, ".@") orelse language.len;
    const n = @min(end, buf.len);
    for (language[0..n], buf[0..n]) |ch, *o| o.* = if (ch == '_') '-' else ch;
    const s = buf[0..n];
    if (std.mem.eql(u8, s, "C") or std.mem.eql(u8, s, "POSIX")) return "";
    return s;
}

fn regionOf(tag: []const u8) ?[]const u8 {
    var it = std.mem.tokenizeScalar(u8, tag, '-');
    _ = it.next();
    while (it.next()) |sub| {
        if (sub.len == 2 and std.ascii.isAlphabetic(sub[0])) return sub;
        if (sub.len == 3 and std.ascii.isDigit(sub[0])) return sub;
    }
    return null;
}

fn order(a: []const u8, b: []const u8) std.math.Order {
    return std.ascii.orderIgnoreCase(a, b);
}

fn lookup(tag: []const u8) ?*const data.Locale {
    var lo: usize = 0;
    var hi: usize = data.locales.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        switch (order(tag, data.locales[mid].tag)) {
            .eq => return &data.locales[mid],
            .lt => hi = mid,
            .gt => lo = mid + 1,
        }
    }
    return null;
}

/// The tag with its likely script, where it is not its language's:
/// "zh-TW" is "zh-Hant-TW".
pub fn alias(tag: []const u8) ?[]const u8 {
    for (data.aliases) |a| if (order(tag, a.from) == .eq) return a.to;
    return null;
}

fn regionFirstDay(region: []const u8) ?u3 {
    for (data.regions) |r| if (order(region, r.region) == .eq) return @intCast(r.first_day);
    return null;
}

// Tests ------------------------------------------------------------------------

const testing = std.testing;

fn fmtDate(l: Locale, days: i64, style: DateStyle) ![]const u8 {
    const S = struct {
        var buf: [256]u8 = undefined;
    };
    var w: Writer = .fixed(&S.buf);
    try l.formatDate(&w, days, style);
    return w.buffered();
}

fn fmtTime(l: Locale, seconds: u32, style: TimeStyle) ![]const u8 {
    const S = struct {
        var buf: [256]u8 = undefined;
    };
    var w: Writer = .fixed(&S.buf);
    try l.formatTime(&w, seconds, style);
    return w.buffered();
}

test "civil dates and days" {
    try testing.expectEqual(Date{ .year = 1970, .month = 1, .day = 1 }, Date.fromDays(0));
    try testing.expectEqual(Date{ .year = 1969, .month = 12, .day = 31 }, Date.fromDays(-1));
    // 2026-10-18 was a Sunday, 20744 days after the epoch.
    try testing.expectEqual(@as(i64, 20744), Date.toDays(.{ .year = 2026, .month = 10, .day = 18 }));
    try testing.expectEqual(@as(u3, 0), weekday(20744));
    try testing.expectEqual(Date{ .year = 2000, .month = 2, .day = 29 }, Date.fromDays(Date.toDays(.{ .year = 2000, .month = 3, .day = 0 })));
    try testing.expectEqual(@as(u8, 29), daysInMonth(2024, 2));
    try testing.expectEqual(@as(u8, 28), daysInMonth(1900, 2));
    try testing.expectEqual(@as(u8, 31), daysInMonth(2026, 12));
    var d: i64 = -800000;
    while (d < 800000) : (d += 997) try testing.expectEqual(d, Date.fromDays(d).toDays());
}

test "dates in English, German, Arabic (Egypt), and Hebrew" {
    const day = Date.toDays(.{ .year = 2026, .month = 10, .day = 18 });
    const en = Locale.find("en-US");
    try testing.expectEqualStrings("Sunday, October 18, 2026", try fmtDate(en, day, .full));
    try testing.expectEqualStrings("10/18/26", try fmtDate(en, day, .short));
    try testing.expectEqualStrings("October 2026", try fmtDate(en, day, .month_year));
    try testing.expectEqualStrings("Su", try fmtDate(en, day, .weekday_short));
    try testing.expectEqualStrings("S", try fmtDate(en, day, .weekday_narrow));
    try testing.expectEqual(@as(u3, 0), en.first_day);
    const de = Locale.find("de_DE.UTF-8");
    try testing.expectEqualStrings("Sonntag, 18. Oktober 2026", try fmtDate(de, day, .full));
    try testing.expectEqualStrings("Oktober 2026", try fmtDate(de, day, .month_year));
    try testing.expectEqual(@as(u3, 1), de.first_day);
    const ar = Locale.find("ar-EG");
    try testing.expectEqualStrings("١٨", try fmtDate(ar, day, .day));
    try testing.expectEqualStrings("الأحد، ١٨ أكتوبر ٢٠٢٦", try fmtDate(ar, day, .full));
    try testing.expectEqual(@as(u3, 6), ar.first_day);
    const he = Locale.find("he");
    try testing.expectEqualStrings("אוקטובר 2026", try fmtDate(he, day, .month_year));
    try testing.expectEqual(@as(u3, 0), he.first_day);
}

test "fallbacks: shorter tags, likely scripts, regions' first days, English" {
    try testing.expectEqualStrings("zh-Hant", Locale.find("zh-TW").tag);
    try testing.expectEqualStrings("zh", Locale.find("zh-CN").tag);
    try testing.expectEqualStrings("de", Locale.find("de-XX").tag);
    try testing.expectEqualStrings("en", Locale.find("").tag);
    try testing.expectEqualStrings("en", Locale.find("C").tag);
    try testing.expectEqualStrings("en", Locale.find("tlh").tag);
    // English in Germany starts its weeks on Monday; German in the US on
    // Sunday.
    try testing.expectEqual(@as(u3, 1), Locale.find("en-DE").first_day);
    try testing.expectEqual(@as(u3, 0), Locale.find("de-US").first_day);
}

test "times: hour cycles, periods first, separators, digits" {
    const t = 22 * 3600 + 5 * 60 + 9;
    const en = Locale.find("en");
    try testing.expectEqual(HourCycle.h12, en.hourCycle());
    try testing.expectEqualStrings("10:05\u{202F}PM", try fmtTime(en, t, .short));
    try testing.expectEqualStrings("10:05:09\u{202F}PM", try fmtTime(en, t, .medium));
    try testing.expectEqualStrings("12", try fmtTime(en, 0, .hour));
    try testing.expectEqualStrings("AM", try fmtTime(en, 0, .period));
    const de = Locale.find("de");
    try testing.expectEqual(HourCycle.h23, de.hourCycle());
    try testing.expectEqualStrings("22:05", try fmtTime(de, t, .short));
    try testing.expectEqualStrings("07", try fmtTime(de, 7 * 3600, .hour));
    const ko = Locale.find("ko");
    try testing.expect(ko.periodFirst() and !en.periodFirst());
    try testing.expectEqualStrings("오후 10:05", try fmtTime(ko, t, .short));
    try testing.expectEqual(@as(u21, '.'), Locale.find("fi").timeSeparator());
    try testing.expectEqual(@as(u21, ':'), de.timeSeparator());
    try testing.expectEqualStrings("١٠:٠٥ م", try fmtTime(Locale.find("ar-EG"), t, .short));
}
